"""Read-only attribution of all perpetual outcomes, actual finish hashes and ledger prefix."""
import gzip,hashlib,importlib.util,json,subprocess
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=Path(__file__).resolve().parent
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()

def main():
 raw=gzip.decompress((ROOT/'research/monitor/configs.json.gz').read_bytes());feed=json.loads(raw);latest=json.loads((ROOT/'research/monitor/latest.json').read_text());by={x['fingerprint']:x for x in feed};assert len(by)==len(feed) and hashlib.sha256(raw).hexdigest()==latest['research']['configs_sha256'];sp=importlib.util.spec_from_file_location('perp_feed_registry',ROOT/'research/automation/registry.py');reg=importlib.util.module_from_spec(sp);sp.loader.exec_module(reg);records=reg.read_records(ROOT/'research/automation/registry.jsonl');report=json.loads((R/'report.json').read_text());forward=json.loads((R/'forward_report.json').read_text());ctx=json.loads((R/'context.json').read_text());count=0
 for c in report['configs'].values():
  row=by[c['fingerprint']];p=records[c['fingerprint']]['spec']['parameters'];assert row['report']==str((R/'report.json').relative_to(ROOT)) and row['status']==c['status'] and row['criteria']==c['criteria'];assert row['capital_usdt']==p['initial_capital_usdt']==10000 and row['start_utc']==p['start_utc'] and row['end_utc']==p['end_utc'] and row['positive_folds_1x']==c['positive_folds_1x'] and row['weights']==[]
  assert row['cross_period_passed'] is False and row['validation']['walk_forward_folds']==13 and row['validation']['cost_scenarios']==['1','2','3'] and (row['validation']['sensitivity_recorded'] or c['role']=='benchmark')
  for k,z in c['scenes'].items():
   s=row['scenes'][k]
   for dest,src in {'return_pct':'net_return_pct','drawdown_pct':'max_drawdown_pct','sharpe':'sharpe_365','cost':'cost_usdt'}.items():assert s[dest]==(round(float(z[src]),6) if z[src] is not None else None)
   assert s['nav_hash']==z['NAV_sha256_f64le'] and s['executions']==z['executions'] and s['round_trips']==z['round_trips'] and s['fold_returns_pct']==[round(float(f['net_return_pct']),6) for f in z['folds']] and s['fold_drawdowns_pct']==[round(float(f['max_drawdown_pct']),6) for f in z['folds']];count+=1
 for c in [*report['configs'].values(),*forward['configs'].values()]:
  partial=c['name'].startswith('forward_snapshot');rec=records[c['fingerprint']];assert rec['result_available'] and rec['status']==('rejected' if partial else c['status']) and rec['report_sha256']==sha(R/('forward_report.json' if partial else 'report.json'))
 assert count==126 and len(report['configs'])==42 and report['summary']['candidate_configs']==36 and report['summary']['benchmark_configs']==6 and len(report['summary']['rejected'])+len(report['summary']['passed'])==42;assert '537f5a8fc4b6e58511fabbde15096659e072be117d9a365d3827ac178134c70e' in by;assert all(sha(ROOT/p)==h for p,h in ctx['account_hashes_before'].items())
 base=json.loads((R/'startup.json').read_text())['head_after_successful_SSH_fetch'];old=subprocess.check_output(['git','show',base+':research/automation/registry.jsonl'],cwd=ROOT);ledger=(ROOT/'research/automation/registry.jsonl').read_bytes();assert hashlib.sha256(old).hexdigest()==ctx['main_registry_sha256_before_reserve'] and ledger.startswith(old);new=[json.loads(x) for x in ledger[len(old):].splitlines()];assert len(new)==90 and len({x['fingerprint'] for x in new})==45
 for name in ['initial_recovery_commands.json','research_commands.json','forward_commands.json',('gates_recovery_commands.json' if (R/'gates_recovery_commands.json').exists() else 'gates_commands.json'),'review_commands.json']:assert all(x['exit_code']==0 for x in json.loads((R/name).read_text())),name
 refs=json.loads((R/'anchors.json').read_text());docs={};assert len(refs)==0
 for name,ref in refs.items():
  path=ref['source_report'];assert sha(ROOT/path)==ref['source_report_sha256']
  if path not in docs:docs[path]=json.loads((ROOT/path).read_text())
  original=docs[path]['configs'][name];rec=records[ref['fingerprint']];row=by[ref['fingerprint']];assert rec['report_sha256']==ref['source_report_sha256'] and rec['status']==ref['original_status']==original['status'];assert row['report']==path and row['status']==original['status'];assert sha(ROOT/ref['source_archive'])==ref['source_archive_sha256'];cell=report['joint_grid_sensitivity']['cells'][name];assert cell['read_only_anchor'] is True and cell['qualification_status']==ref['original_status']
  for k,z in original['scenes'].items():assert row['scenes'][k]['nav_hash']==z['NAV_sha256_f64le'] and row['scenes'][k]['return_pct']==round(z['net_return_pct'],6)
 assert len(report['joint_grid_sensitivity']['cells'])==36 and report['summary']['read_only_anchor_configs']==0
 assert sha(R/'report.json')==json.loads((R/'verification.json').read_text())['report_sha256'] and sha(R/'forward_report.json')==json.loads((R/'forward_verification.json').read_text())['report_sha256'];result={'passed':True,'research_configs':len(feed),'paper_observations':latest['paper']['observation_count'],'paper_accounts':len(latest['paper']['accounts']),'new_financial_configs_verified':42,'rejected_candidates':sum(c['role']=='candidate' and c['status']=='rejected' for c in report['configs'].values()),'passed_candidates':len(report['summary']['passed']),'new_benchmarks':6,'old_anchor_results_read_only':0,'new_cost_scenes_verified':count,'positive_candidate_configs_by_cost':{k:sum(c['role']=='candidate' and c['scenes'][k]['net_return_pct']>0 for c in report['configs'].values()) for k in ['1','2','3']},'new_actual_partial_observations':3,'main_registry_append_only_events':90,'regression_alias_retained':True,'raw_fixed_entry_fractions':[.1,.2,.3],'entry_notionals_usdt':[1000,2000,3000],'initial_collateral_usdt':10000,'perpetual_funding_and_margin_scope_in_report':True,'buffer_exit_hysteresis':True,'no_old_anchor_reregistration_or_rerating':True,'whole_sensitivity_grid_configs':36,'new_parent_backtests':0,'required_gates_actual_exit0':True,'financial_report_sha256':sha(R/'report.json'),'forward_report_sha256':sha(R/'forward_report.json'),'protected_inputs_unchanged':True};(R/'feed_verification.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps(result),flush=True)

if __name__=='__main__':main()
